-- V7 migration is intentionally additive. Run once in Supabase SQL Editor.
alter table public.events add column if not exists image_url text;
alter table public.event_participants drop constraint if exists event_participants_status_check;
alter table public.event_participants add constraint event_participants_status_check check(status in('going','not_going','maybe'));
create table if not exists public.event_comments(id bigint generated by default as identity primary key,event_id bigint not null references public.events(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 1000),created_at timestamptz not null default now());
alter table public.event_comments enable row level security;
drop policy if exists "members read event comments" on public.event_comments; drop policy if exists "members add own event comments" on public.event_comments; drop policy if exists "members delete own event comments" on public.event_comments;
create policy "members read event comments" on public.event_comments for select to authenticated using(true);
create policy "members add own event comments" on public.event_comments for insert to authenticated with check(auth.uid()=user_id);
create policy "members delete own event comments" on public.event_comments for delete to authenticated using(auth.uid()=user_id or public.is_suura_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('event-media','event-media',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "members read event media" on storage.objects; drop policy if exists "admins upload event media" on storage.objects; drop policy if exists "admins delete event media" on storage.objects;
create policy "members read event media" on storage.objects for select using(bucket_id='event-media');
create policy "admins upload event media" on storage.objects for insert to authenticated with check(bucket_id='event-media' and public.is_suura_admin());
create policy "admins delete event media" on storage.objects for delete to authenticated using(bucket_id='event-media' and public.is_suura_admin());

create table if not exists public.elections(id bigint generated by default as identity primary key,title text not null,description text,starts_at timestamptz not null,ends_at timestamptz not null,rules_pdf_path text,status text not null default 'draft' check(status in('draft','open','closed')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.election_candidates(id bigint generated by default as identity primary key,election_id bigint not null references public.elections(id) on delete cascade,name text not null,statement text,photo_url text,sort_order int not null default 0);
create table if not exists public.election_codes(id bigint generated by default as identity primary key,election_id bigint not null references public.elections(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,code_hash text not null,code_hint text,used_at timestamptz,created_at timestamptz not null default now(),unique(election_id,user_id),unique(election_id,code_hash));
create table if not exists public.election_ballots(id bigint generated by default as identity primary key,election_id bigint not null references public.elections(id) on delete cascade,candidate_id bigint not null references public.election_candidates(id) on delete cascade,receipt uuid not null default gen_random_uuid() unique,cast_at timestamptz not null default now());
alter table public.elections enable row level security; alter table public.election_candidates enable row level security; alter table public.election_codes enable row level security; alter table public.election_ballots enable row level security;
drop policy if exists "members read elections" on public.elections; drop policy if exists "admins manage elections" on public.elections; drop policy if exists "members read candidates" on public.election_candidates; drop policy if exists "admins manage candidates" on public.election_candidates; drop policy if exists "member reads own election code" on public.election_codes; drop policy if exists "admins manage election codes" on public.election_codes; drop policy if exists "admins read ballots" on public.election_ballots;
create policy "members read elections" on public.elections for select to authenticated using(true); create policy "admins manage elections" on public.elections for all to authenticated using(public.is_suura_admin()) with check(public.is_suura_admin());
create policy "members read candidates" on public.election_candidates for select to authenticated using(true); create policy "admins manage candidates" on public.election_candidates for all to authenticated using(public.is_suura_admin()) with check(public.is_suura_admin());
create policy "member reads own election code" on public.election_codes for select to authenticated using(auth.uid()=user_id or public.is_suura_admin()); create policy "admins manage election codes" on public.election_codes for all to authenticated using(public.is_suura_admin()) with check(public.is_suura_admin()); create policy "admins read ballots" on public.election_ballots for select to authenticated using(public.is_suura_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('election-docs','election-docs',false,10485760,array['application/pdf']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['application/pdf'];
drop policy if exists "members read election docs" on storage.objects; drop policy if exists "admins upload election docs" on storage.objects; drop policy if exists "admins delete election docs" on storage.objects;
create policy "members read election docs" on storage.objects for select to authenticated using(bucket_id='election-docs'); create policy "admins upload election docs" on storage.objects for insert to authenticated with check(bucket_id='election-docs' and public.is_suura_admin()); create policy "admins delete election docs" on storage.objects for delete to authenticated using(bucket_id='election-docs' and public.is_suura_admin());

create or replace function public.assign_election_code(p_election_id bigint,p_user_id uuid,p_code text) returns void language plpgsql security definer set search_path=public,extensions as $$ begin if not public.is_suura_admin() then raise exception 'Yetkisiz işlem'; end if; if length(trim(p_code))<4 then raise exception 'Kod en az 4 karakter olmalı'; end if; insert into public.election_codes(election_id,user_id,code_hash,code_hint) values(p_election_id,p_user_id,encode(digest(trim(p_code),'sha256'),'hex'),right(trim(p_code),2)) on conflict(election_id,user_id) do update set code_hash=excluded.code_hash,code_hint=excluded.code_hint,used_at=null; end $$;
create or replace function public.cast_election_vote(p_election_id bigint,p_candidate_id bigint,p_code text) returns uuid language plpgsql security definer set search_path=public,extensions as $$ declare c public.election_codes%rowtype; e public.elections%rowtype; r uuid; begin select * into e from public.elections where id=p_election_id; if e.id is null or e.status<>'open' or now()<e.starts_at or now()>e.ends_at then raise exception 'Seçim oy kullanımına açık değil'; end if; if not exists(select 1 from public.election_candidates where id=p_candidate_id and election_id=p_election_id) then raise exception 'Geçersiz aday'; end if; select * into c from public.election_codes where election_id=p_election_id and user_id=auth.uid() for update; if c.id is null then raise exception 'Hesabına seçim kodu atanmamış'; end if; if c.used_at is not null then raise exception 'Bu hesap seçimde daha önce oy kullandı'; end if; if c.code_hash<>encode(digest(trim(p_code),'sha256'),'hex') then raise exception 'Seçim kodu hatalı'; end if; update public.election_codes set used_at=now() where id=c.id; insert into public.election_ballots(election_id,candidate_id) values(p_election_id,p_candidate_id) returning receipt into r; return r; end $$;
create or replace function public.get_election_results(p_election_id bigint) returns table(candidate_id bigint,candidate_name text,votes bigint) language sql security definer set search_path=public as $$ select c.id,c.name,count(b.id) from public.election_candidates c left join public.election_ballots b on b.candidate_id=c.id where c.election_id=p_election_id group by c.id,c.name,c.sort_order order by c.sort_order,c.id $$;
